nome = input("Informe o seu nome: ")
formacaoProfissional = input("Informe a sua formação profissional ou curso em que está se formando: ")
primeiroAdjetivo = input("Como você descreveria a sua turma de estudos em uma palavra?: ")
segundoAdjetivo = input("Como você descreveria o instrutor do curso em uma palavra?: ")
primeiraComida = input("Qual a comida que você mais gostou no almoço?: ")
segundaComida = input("E o que você escolheu para beber ou acompanhar? ")
sentimento = input("Qual sentimento descreveria você, ao final do dia, após a participação no curso?: ")

print(f"{nome} começou hoje o seu primeiro curso na Generation Brasil. Está cursando a formação em {formacaoProfissional}. Achou a sua turma muito {primeiroAdjetivo} mas o instrutor era, no mínimo, {segundoAdjetivo}. No almoço, comeu {primeiraComida} e {segundaComida} enquanto revisava as suas anotações. Ao final do dia, sente-se {sentimento}, mas tem a determinação de concluir a jornada.")